export const originalPersonalHomeComponent="function EmployeePersonalHomeView({\r\n  computedHome = null,\n  employee,\r\n  currentCompany = null,\r\n  employees = [],\r\n  attendance = {},\r\n  date = getTodayString(),\r\n  financials = [],\r\n  performance = {},\r\n  customers = [],\r\n  orders = [],\r\n  payments = [],\r\n  expenses = [],\r\n  holidays = [],\r\n  employeeReviews = [],\r\n  deliveryReports = [],\r\n  advanceRequests = [],\r\n  assets = [],\r\n  assetCostLogs = [],\r\n  setActiveTab = () => {},\r\n  record = null,\r\n  notificationUnreadCount = 0,\r\n  onOpenNotifications = () => {},\r\n  showDeliveryReportHome = true\r\n}) {\r\n  const reviewSectionRef = useRef(null);\r\n  const payrollPdfRef = useRef(null);\r\n  const [payrollPdfStatus, setPayrollPdfStatus] = useState('');\r\n  const monthKey = buildMonthKeyFromDate(date || getTodayString());\r\n  const details = useMemo(() => (\r\n    (computedHome ? computedHome.details : buildSalaryDetails(employee?.id, employees, attendance, financials, performance, customers, orders, payments, holidays, monthKey))\n      || { netSalary: 0, grossSalary: 0, deductionTotal: 0, workDays: 0, baseSalaryCalc: 0, supportSalary: 0, responsibilitySalary: 0, experienceSalary: 0, commission: 0, tieredBonus: 0, overtimePay: 0, totalBonus: 0, holidayBonus: 0, totalPenalty: 0, totalAdvance: 0, totalEmployeePurchase: 0, badDebt: 0, salesRevenue: 0, attendanceEntries: [], bonusRecords: [], penaltyRecords: [], advanceRecords: [], employeePurchaseRecords: [] }\r\n  ), [attendance, customers, computedHome, employee?.id, employees, financials, holidays, monthKey, orders, payments, performance]);\n  const employeeShiftPolicy = useMemo(() => resolveEmployeeShiftPolicy(employee || {}), [employee]);\r\n  const todayRecord = useMemo(() => {\r\n    const rawRecord = (employee?.id ? attendance?.[`${date}_${employee.id}`] : null) || record || null;\r\n    return normalizeAttendanceRecordForWorkDate(rawRecord, employee || {}, date);\r\n  }, [attendance, date, employee, record]);\r\n  const todayAttendanceTiming = useMemo(() => (\r\n    todayRecord\r\n      ? calculateAttendanceTiming(employee || {}, { ...todayRecord, date })\r\n      : { lateMinutes: 0, earlyOvertimeMinutes: 0, afterShiftOvertimeMinutes: 0, autoOvertimeMinutes: 0 }\r\n  ), [date, employee, todayRecord]);\r\n  const attendanceStatus = todayRecord?.status === 'leave'\r\n    ? 'Nghỉ phép'\r\n    : todayRecord?.checkIn && todayRecord?.checkOut\r\n      ? 'Đã ra ca'\r\n      : todayRecord?.checkIn\r\n        ? 'Đang làm'\r\n        : 'Chưa chấm';\r\n  const attendanceTone = todayRecord?.checkIn\r\n    ? (todayRecord?.checkOut ? 'emerald' : 'blue')\r\n    : todayRecord?.status === 'leave'\r\n      ? 'amber'\r\n      : 'rose';\r\n  const pendingAdvanceRows = useMemo(() => (\r\n    (advanceRequests || []).filter(req => (\r\n      `${req?.empId || req?.employeeId || ''}` === `${employee?.id || ''}` &&\r\n      req?.status === 'pending' &&\r\n      !req?.isArchived &&\r\n      isSalaryAdvanceInMonth(req, monthKey)\r\n    ))\r\n  ), [advanceRequests, employee?.id, monthKey]);\r\n  const pendingAdvanceAmount = pendingAdvanceRows.reduce((sum, req) => sum + parseLooseMoneyValue(req.amount), 0);\r\n  const reviewSummary = useMemo(() => (\r\n    computedHome ? computedHome.reviewSummary : employee?.id\n      ? buildEmployeeReviewSummary(employee, { attendance, orders, deliveryReports, reviews: employeeReviews, monthKey })\r\n      : null\r\n  ), [attendance, computedHome, deliveryReports, employee, employeeReviews, monthKey, orders]);\n  const isEmployeeDeliveryReportRow = (row = {}) => {\r\n    const employeeId = `${employee?.id || ''}`;\r\n    if (!employeeId) return false;\r\n    return [\r\n      row.empId,\r\n      row.employeeId,\r\n      row.driverId,\r\n      row.createdByEmpId,\r\n      row.createdBy,\r\n      row.createdByEmployeeId\r\n    ].some(id => `${id || ''}` === employeeId);\r\n  };\r\n  const isRowInHomeMonth = (row = {}) => {\r\n    const key = getDateKeyFromAnyValue(row.date || row.dateKey || row.createdAt || row.updatedAt || getEntityTimestamp(row));\r\n    return Boolean(key) && buildMonthKeyFromDate(key) === monthKey;\r\n  };\r\n  const employeeDeliveryMonthReports = useMemo(() => (\r\n    (deliveryReports || [])\r\n      .filter(report => report && !report.isArchived && isEmployeeDeliveryReportRow(report) && isRowInHomeMonth(report))\r\n  ), [deliveryReports, employee?.id, monthKey]);\r\n  const employeeDeliveryMonthStandaloneExpenses = useMemo(() => (\r\n    (expenses || [])\r\n      .filter(expense => (\r\n        expense &&\r\n        !expense.isArchived &&\r\n        expense.sourceType === 'driver_delivery_standalone_expense' &&\r\n        isEmployeeDeliveryReportRow(expense) &&\r\n        isRowInHomeMonth(expense)\r\n      ))\r\n  ), [employee?.id, expenses, monthKey]);\r\n  const employeeDeliveryMonthSummary = useMemo(() => {\r\n    const dayMap = new Map();\r\n    const ensureDay = (dateKey = '') => {\r\n      const key = dateKey;\r\n      if (!key) return null;\r\n      if (!dayMap.has(key)) {\r\n        dayMap.set(key, { date: key, reportCount: 0, income: 0, expense: 0 });\r\n      }\r\n      return dayMap.get(key);\r\n    };\r\n    employeeDeliveryMonthReports.forEach(report => {\r\n      const key = getDateKeyFromAnyValue(report.date || report.dateKey || report.createdAt || report.updatedAt || getEntityTimestamp(report));\r\n      const row = ensureDay(key);\r\n      if (!row) return;\r\n      row.reportCount += 1;\r\n      row.income += parseLooseMoneyValue(report.collectedAmount);\r\n      row.expense += parseLooseMoneyValue(report.deliveryExpenseAmount);\r\n    });\r\n    employeeDeliveryMonthStandaloneExpenses.forEach(expense => {\r\n      const key = getDateKeyFromAnyValue(expense.date || expense.dateKey || expense.createdAt || expense.updatedAt || getEntityTimestamp(expense));\r\n      const row = ensureDay(key);\r\n      if (!row) return;\r\n      row.expense += parseLooseMoneyValue(expense.amount);\r\n    });\r\n    const rows = Array.from(dayMap.values()).sort((a, b) => `${b.date}`.localeCompare(`${a.date}`));\r\n    return {\r\n      income: rows.reduce((sum, row) => sum + row.income, 0),\r\n      expense: rows.reduce((sum, row) => sum + row.expense, 0),\r\n      reportCount: employeeDeliveryMonthReports.length,\r\n      rows\r\n    };\r\n  }, [employeeDeliveryMonthReports, employeeDeliveryMonthStandaloneExpenses]);\r\n  const recentSalaryRows = useMemo(() => (\r\n    [\r\n      ...(details.bonusRecords || []).map(row => ({ ...row, kindLabel: 'Thưởng', tone: 'good', sign: '+' })),\r\n      ...(details.penaltyRecords || []).map(row => ({ ...row, kindLabel: 'Phạt', tone: 'bad', sign: '-' })),\r\n      ...(details.advanceRecords || []).map(row => ({ ...row, kindLabel: 'Ứng', tone: 'warn', sign: '-' })),\r\n      ...(details.employeePurchaseRecords || []).map(row => ({ ...row, kindLabel: 'Mua hàng', tone: 'bad', sign: '-' }))\r\n    ]\r\n      .sort((a, b) => (getEntityTimestamp(b) || new Date(b.date || 0).getTime() || 0) - (getEntityTimestamp(a) || new Date(a.date || 0).getTime() || 0))\r\n      .slice(0, 5)\r\n  ), [details.advanceRecords, details.bonusRecords, details.employeePurchaseRecords, details.penaltyRecords]);\r\n  const totalBonusDisplay = parseLooseMoneyValue(details.totalBonus) + parseLooseMoneyValue(details.tieredBonus);\r\n  const totalPenaltyDisplay = parseLooseMoneyValue(details.totalPenalty) + parseLooseMoneyValue(details.badDebt);\r\n  const payrollSummaryRows = useMemo(() => {\r\n    const rows = [\r\n      { label: 'Thực lĩnh', amount: parseLooseMoneyValue(details.netSalary), group: 'total', tone: parseLooseMoneyValue(details.netSalary) < 0 ? 'bad' : 'good' },\r\n      { label: 'Lương cơ bản', amount: parseLooseMoneyValue(details.baseSalaryCalc), group: 'income' },\r\n      { label: 'Hỗ trợ + trách nhiệm', amount: parseLooseMoneyValue(details.supportSalary) + parseLooseMoneyValue(details.responsibilitySalary), group: 'income' },\r\n      { label: 'Lương theo bộ phận', amount: parseLooseMoneyValue(details.roleSalary), group: 'income' },\r\n      { label: 'Lương thâm niên', amount: parseLooseMoneyValue(details.experienceSalary), group: 'income' },\r\n      { label: 'Hoa hồng', amount: parseLooseMoneyValue(details.commission), group: 'income' },\r\n      { label: 'Tăng ca', amount: parseLooseMoneyValue(details.overtimePay), group: 'income' },\r\n      { label: 'Thưởng', amount: totalBonusDisplay, group: 'income' },\r\n      { label: 'Tổng bị trừ', amount: parseLooseMoneyValue(details.deductionTotal), group: 'deduction' },\r\n      { label: 'Ứng lương', amount: parseLooseMoneyValue(details.totalAdvance), group: 'deduction' },\r\n      { label: 'Mua hàng nội bộ', amount: parseLooseMoneyValue(details.totalEmployeePurchase), group: 'deduction' },\r\n      { label: 'Công nợ phải thu', amount: parseLooseMoneyValue(details.badDebt), group: 'deduction' }\r\n    ];\r\n    const groupRank = row => row.amount === 0 ? 3 : row.group === 'deduction' ? 2 : row.group === 'total' ? 0 : 1;\r\n    return rows\r\n      .map((row, index) => ({ ...row, order: index }))\r\n      .filter(row => row.amount !== 0)\r\n      .sort((a, b) => groupRank(a) - groupRank(b) || a.order - b.order);\r\n  }, [details, totalBonusDisplay]);\r\n  const handleCreatePayrollPdf = async () => {\r\n    if (!payrollPdfRef.current) return;\r\n    setPayrollPdfStatus('Đang tạo PDF bảng lương...');\r\n    try {\r\n      const [{ toPng }, { jsPDF }] = await Promise.all([\r\n        import('html-to-image'),\r\n        import('jspdf')\r\n      ]);\r\n      const dataUrl = await toPng(payrollPdfRef.current, {\r\n        cacheBust: true,\r\n        pixelRatio: 2,\r\n        backgroundColor: '#ffffff'\r\n      });\r\n      const image = new Image();\r\n      image.src = dataUrl;\r\n      await new Promise((resolve, reject) => {\r\n        image.onload = resolve;\r\n        image.onerror = reject;\r\n      });\r\n      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });\r\n      const margin = 12;\r\n      const pageWidth = 210;\r\n      const pageHeight = 297;\r\n      const contentWidth = pageWidth - (margin * 2);\r\n      const imageHeight = (image.height / image.width) * contentWidth;\r\n      const pageContentHeight = pageHeight - (margin * 2);\r\n      let renderedHeight = 0;\r\n      while (renderedHeight < imageHeight) {\r\n        pdf.addImage(dataUrl, 'PNG', margin, margin - renderedHeight, contentWidth, imageHeight);\r\n        renderedHeight += pageContentHeight;\r\n        if (renderedHeight < imageHeight) pdf.addPage();\r\n      }\r\n      const employeeName = sanitizeShareFileName(employee?.name || 'nhan-su');\r\n      pdf.save(`bang-luong-${employeeName}-${monthKey}.pdf`);\r\n      setPayrollPdfStatus('Đã tạo file PDF bảng lương.');\r\n    } catch (error) {\r\n      console.error('Không thể tạo PDF bảng lương:', error);\r\n      setPayrollPdfStatus('Không thể tạo PDF. Vui lòng thử lại.');\r\n    }\r\n  };\r\n  const employeeAssignedAssets = useMemo(() => {\r\n    if (!employee?.id) return [];\r\n    return (assets || [])\r\n      .filter(asset => asset && !asset.isArchived && isAssetAssignedToEmployee(asset, employee.id))\r\n      .sort((a, b) => getAssetDisplayLabel(a).localeCompare(getAssetDisplayLabel(b), 'vi'));\r\n  }, [assets, employee?.id]);\r\n  const assignedAssetIds = useMemo(() => new Set(employeeAssignedAssets.map(asset => `${asset.id || ''}`).filter(Boolean)), [employeeAssignedAssets]);\r\n  const employeeAssetCostRows = useMemo(() => {\r\n    if (!assignedAssetIds.size) return [];\r\n    return (assetCostLogs || []).filter(log => log && !log.isArchived && assignedAssetIds.has(`${log.assetId || ''}`));\r\n  }, [assetCostLogs, assignedAssetIds]);\r\n  const employeeAssetExpenseRows = useMemo(() => {\r\n    if (!assignedAssetIds.size) return [];\r\n    return (expenses || []).filter(expense => (\r\n      expense && !expense.isArchived &&\r\n      assignedAssetIds.has(`${expense.assetId || expense.deliveryExpenseAssetId || ''}`) &&\r\n      !expense.assetCostLogId &&\r\n      !expense.relatedAssetCostLogId &&\r\n      !expense.sourceAssetCostLogId\r\n    ));\r\n  }, [assignedAssetIds, expenses]);\r\n  const isAssetRowInCurrentMonth = (row = {}) => {\r\n    const key = getDateKeyFromAnyValue(row.date || row.createdAt || row.updatedAt);\r\n    return Boolean(key) && buildMonthKeyFromDate(key) === monthKey;\r\n  };\r\n  const employeeAssetMonthCost = useMemo(() => (\r\n    employeeAssetCostRows.reduce((sum, log) => (isAssetRowInCurrentMonth(log) ? sum + parseLooseMoneyValue(log.amount) : sum), 0) +\r\n    employeeAssetExpenseRows.reduce((sum, expense) => (isAssetRowInCurrentMonth(expense) ? sum + parseLooseMoneyValue(expense.amount) : sum), 0)\r\n  ), [employeeAssetCostRows, employeeAssetExpenseRows, monthKey]);\r\n  const latestEmployeeAssetCost = useMemo(() => (\r\n    [...employeeAssetCostRows, ...employeeAssetExpenseRows]\r\n      .sort((a, b) => (getEntityTimestamp(b) || Date.parse(b.date || b.createdAt || '') || 0) - (getEntityTimestamp(a) || Date.parse(a.date || a.createdAt || '') || 0))[0] || null\r\n  ), [employeeAssetCostRows, employeeAssetExpenseRows]);\r\n  const latestEmployeeAssetCostLabel = latestEmployeeAssetCost\r\n    ? (latestEmployeeAssetCost.assetCostLogId || latestEmployeeAssetCost.relatedAssetCostLogId || latestEmployeeAssetCost.sourceAssetCostLogId\r\n        ? normalizeExpenseCategoryLabel(latestEmployeeAssetCost.category || latestEmployeeAssetCost.note || 'Chi phí tài sản')\r\n        : getAssetCostTypeLabel(latestEmployeeAssetCost.type || latestEmployeeAssetCost.costType || 'other'))\r\n    : '';\r\n  const positionLabel = getEmployeePositionLabel(employee?.position);\r\n  const isSalesEmployeeHome = isEmployeeSalesPosition(employee);\r\n  const isAssetHomeRole = isEmployeeDriverPosition(employee) || employeeHasPosition(employee, 'Sản xuất');\r\n  const shouldShowAssetHomeTile = isAssetHomeRole || employeeAssignedAssets.length > 0;\r\n  const employeeSalesOrderRows = useMemo(() => {\r\n    if (!isSalesEmployeeHome || !employee?.id) return [];\r\n    const employeeId = `${employee.id}`;\r\n    return (orders || []).filter(order => {\r\n      if (!order || order.isArchived) return false;\r\n      const orderSalesEmpId = getOrderSalesEmpId(order, customers || []);\r\n      if (`${orderSalesEmpId || ''}` !== employeeId) return false;\r\n      const orderDateKey = getDateKeyFromAnyValue(order.date || order.createdAt || order.updatedAt || getEntityTimestamp(order));\r\n      return Boolean(orderDateKey) && buildMonthKeyFromDate(orderDateKey) === monthKey;\r\n    });\r\n  }, [customers, employee?.id, isSalesEmployeeHome, monthKey, orders]);\r\n  const salesOrderCount = employeeSalesOrderRows.length;\r\n  const salesCustomerCount = new Set(employeeSalesOrderRows.map(order => order.customerId).filter(Boolean)).size;\r\n  const shouldShowSalesHomeStats = isSalesEmployeeHome && ((details.salesRevenue || 0) > 0 || salesOrderCount > 0);\r\n  const handleOpenReviewSection = () => {\r\n    setActiveTab?.('employee_reviews');\r\n  };\r\n\r\n  return (\r\n    <div className=\"space-y-5\">\r\n      <div className=\"hd-staff-greeting-surface rounded-lg p-5\">\r\n        <div className=\"flex items-start justify-between gap-3\">\r\n          <div className=\"min-w-0 flex-1\">\r\n            <button type=\"button\" className=\"w-full min-w-0 text-left\" onClick={() => setActiveTab('profile')} aria-label=\"Mở hồ sơ cá nhân\">\r\n              <AccountGreeting name={employee?.name || 'Bạn'} companyName={getCompanyDisplayName(currentCompany)} logoUrl={getCompanyLogoUrl(currentCompany)} />\r\n            </button>\r\n            <div className=\"mt-1 flex flex-wrap items-center gap-2 text-sm font-semibold text-emerald-50\">\r\n              <span>{positionLabel} • {formatMonthYearLabel(monthKey)}</span>\r\n              <button\r\n                type=\"button\"\r\n                onClick={handleOpenReviewSection}\r\n                className=\"inline-flex items-center gap-1 rounded-full bg-white/18 px-2.5 py-1 text-xs font-black text-white ring-1 ring-white/25\"\r\n                aria-label=\"Xem đánh giá tháng\"\r\n              >\r\n                <Star size={13} fill=\"currentColor\" className=\"text-amber-200\" />\r\n                {reviewSummary ? `${reviewSummary.stars} sao` : 'Chưa có đánh giá'}\r\n              </button>\r\n            </div>\r\n          </div>\r\n          <div className=\"flex shrink-0 items-center gap-2\">\r\n            <button\r\n              type=\"button\"\r\n              onClick={onOpenNotifications}\r\n              className=\"relative inline-flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-white/15 text-white ring-1 ring-white/25\"\r\n              aria-label=\"Thông báo\"\r\n            >\r\n              <Bell size={20} />\r\n              {notificationUnreadCount > 0 && (\r\n                <span className=\"absolute -right-1 -top-1 rounded-full bg-rose-500 px-1.5 py-0.5 text-[10px] font-black text-white\">{notificationUnreadCount > 9 ? '9+' : notificationUnreadCount}</span>\r\n              )}\r\n            </button>\r\n          </div>\r\n        </div>\r\n        <div className={`mt-5 grid gap-1.5 sm:gap-2 ${shouldShowAssetHomeTile ? 'grid-cols-3' : 'grid-cols-2'}`}>\r\n          <div className=\"rounded-2xl bg-white/15 px-2 py-3 text-center\">\r\n            <p className=\"text-[9px] font-black uppercase tracking-wide text-emerald-100\">Thực lĩnh</p>\r\n            <p className=\"mt-1 text-sm font-black sm:text-lg\">{formatCurrency(details.netSalary)} đ</p>\r\n          </div>\r\n          <div className=\"rounded-2xl bg-white/15 px-2 py-3 text-center\">\r\n            <p className=\"text-[9px] font-black uppercase tracking-wide text-emerald-100\">Công tháng</p>\r\n            <p className=\"mt-1 text-sm font-black sm:text-lg\">{formatNumber(details.workDays)}</p>\r\n          </div>\r\n          {shouldShowAssetHomeTile && (\r\n            <button\r\n              type=\"button\"\r\n              onClick={() => setActiveTab('asset_management')}\r\n              className=\"rounded-2xl bg-white/15 px-2 py-3 text-center transition active:scale-[0.98]\"\r\n            >\r\n              <p className=\"text-[9px] font-black uppercase tracking-wide text-emerald-100\">QL tài sản</p>\r\n              <p className=\"mt-1 text-sm font-black sm:text-lg\">{formatNumber(employeeAssignedAssets.length)}</p>\r\n            </button>\r\n          )}\r\n        </div>\r\n      </div>\r\n\r\n      {shouldShowSalesHomeStats && (\r\n        <div className=\"grid grid-cols-2 gap-3\">\r\n          <EmployeeHomeStatCard label=\"Doanh thu\" value={`${formatCurrency(details.salesRevenue || 0)} đ`} icon={TrendingUp} tone=\"emerald\" />\r\n          <EmployeeHomeStatCard label=\"Doanh số\" value={`${formatNumber(salesOrderCount)} đơn${salesCustomerCount ? ` • ${formatNumber(salesCustomerCount)} khách` : ''}`} icon={Receipt} tone=\"blue\" />\r\n        </div>\r\n      )}\r\n\r\n      {(employeeAssignedAssets.length > 0 || employeeAssetMonthCost > 0) && (\r\n        <section className=\"rounded-[2rem] border border-sky-100 bg-white p-4 shadow-sm\">\r\n          <div className=\"mb-3 flex items-center justify-between gap-2\">\r\n            <div>\r\n              <p className=\"text-xs font-black uppercase tracking-widest text-sky-600\">QL tài sản</p>\r\n              <h3 className=\"mt-1 text-lg font-black text-slate-950\">Tài sản được bàn giao</h3>\r\n            </div>\r\n            <button type=\"button\" onClick={() => setActiveTab('asset_management')} className=\"rounded-full bg-sky-50 px-3 py-1.5 text-xs font-black text-sky-700\">Mở</button>\r\n          </div>\r\n          <div className=\"grid grid-cols-2 gap-2\">\r\n            <EmployeeHomeQuickRow label=\"Số tài sản\" value={`${formatNumber(employeeAssignedAssets.length)} tài sản`} tone={employeeAssignedAssets.length ? 'good' : 'slate'} />\r\n            <EmployeeHomeQuickRow label=\"Chi phí tháng\" value={`${formatCurrency(employeeAssetMonthCost)} đ`} tone={employeeAssetMonthCost > 0 ? 'warn' : 'slate'} />\r\n          </div>\r\n          {latestEmployeeAssetCost && (\r\n            <p className=\"mt-3 rounded-2xl bg-amber-50 px-3 py-2 text-xs font-bold text-amber-700\">\r\n              Gần nhất: {latestEmployeeAssetCostLabel || 'Chi phí tài sản'} • {formatCurrency(parseLooseMoneyValue(latestEmployeeAssetCost.amount))} đ\r\n            </p>\r\n          )}\r\n          <div className=\"mt-3 space-y-2\">\r\n            {employeeAssignedAssets.slice(0, 3).map(asset => {\r\n              const assetId = `${asset.id || ''}`;\r\n              const assetMonthCost = [\r\n                ...employeeAssetCostRows.filter(log => `${log.assetId || ''}` === assetId),\r\n                ...employeeAssetExpenseRows.filter(expense => `${expense.assetId || expense.deliveryExpenseAssetId || ''}` === assetId)\r\n              ].reduce((sum, row) => (isAssetRowInCurrentMonth(row) ? sum + parseLooseMoneyValue(row.amount) : sum), 0);\r\n              return (\r\n                <div key={asset.id} className=\"flex items-center justify-between gap-3 rounded-2xl border border-slate-100 bg-slate-50 px-3 py-2\">\r\n                  <div className=\"min-w-0\">\r\n                    <p className=\"truncate text-sm font-black text-slate-900\">{getAssetDisplayLabel(asset)}</p>\r\n                    <p className=\"text-xs font-semibold text-slate-500\">{getAssetStatusLabel(asset.status)}</p>\r\n                  </div>\r\n                  <span className=\"shrink-0 text-right text-xs font-black text-sky-700\">{formatCurrency(assetMonthCost)} đ</span>\r\n                </div>\r\n              );\r\n            })}\r\n          </div>\r\n        </section>\r\n      )}\r\n\r\n      <section ref={reviewSectionRef} className=\"scroll-mt-24 rounded-[2rem] border border-slate-100 bg-white p-4 shadow-sm\">\r\n        <div className=\"mb-3\">\r\n          <div className=\"flex flex-wrap items-center justify-between gap-2\">\r\n            <div className=\"flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1\">\r\n              <p className=\"text-xs font-black uppercase tracking-widest text-emerald-600\">Chấm công hôm nay</p>\r\n              <span className=\"text-sm font-black text-slate-950\">{formatDateLabel(date)}</span>\r\n            </div>\r\n          <span className={`rounded-full px-3 py-1 text-xs font-black ${attendanceTone === 'emerald' ? 'bg-emerald-50 text-emerald-700' : attendanceTone === 'blue' ? 'bg-blue-50 text-blue-700' : attendanceTone === 'amber' ? 'bg-amber-50 text-amber-700' : 'bg-rose-50 text-rose-700'}`}>{attendanceStatus}</span>\r\n          </div>\r\n          <p className=\"mt-1 text-xs font-bold text-slate-500\">\r\n            {employeeShiftPolicy.shiftName} • {formatShiftRangeLabel(employeeShiftPolicy)}\r\n          </p>\r\n        </div>\r\n        <div className=\"grid grid-cols-2 gap-2\">\r\n          <EmployeeHomeQuickRow\r\n            label=\"Vào\"\r\n            value={todayRecord?.checkIn ? formatAttendanceMomentForWorkDate(todayRecord.checkIn, date, employee, 'checkIn') : '-'}\r\n            tone={todayRecord?.checkIn ? 'good' : 'bad'}\r\n            secondary={getAttendanceCompactSource(todayRecord, 'checkIn')}\r\n          />\r\n          <EmployeeHomeQuickRow\r\n            label=\"Ra\"\r\n            value={todayRecord?.checkOut ? formatAttendanceMomentForWorkDate(todayRecord.checkOut, date, employee, 'checkOut') : '-'}\r\n            tone={todayRecord?.checkOut ? 'good' : 'warn'}\r\n            secondary={getAttendanceCompactSource(todayRecord, 'checkOut')}\r\n          />\r\n        </div>\r\n        {todayRecord && (todayAttendanceTiming.lateMinutes > 0 || todayAttendanceTiming.autoOvertimeMinutes > 0) && (\r\n          <div className=\"mt-3 flex flex-wrap gap-2 text-xs font-black\">\r\n            {todayAttendanceTiming.lateMinutes > 0 && (\r\n              <span className=\"rounded-full bg-rose-50 px-3 py-1.5 text-rose-700\">Đi muộn {formatNumber(todayAttendanceTiming.lateMinutes)} phút</span>\r\n            )}\r\n            {todayAttendanceTiming.autoOvertimeMinutes > 0 && (\r\n              <span className=\"rounded-full bg-blue-50 px-3 py-1.5 text-blue-700\">Tăng ca {formatNumber(todayAttendanceTiming.autoOvertimeMinutes)} phút</span>\r\n            )}\r\n          </div>\r\n        )}\r\n        <button type=\"button\" onClick={() => setActiveTab('company_attendance')} className=\"mt-3 w-full rounded-2xl bg-emerald-600 px-4 py-3 text-sm font-black text-white shadow-lg shadow-emerald-100\">\r\n          Mở chấm công\r\n        </button>\r\n      </section>\r\n\r\n      <section className=\"rounded-[2rem] border border-slate-100 bg-white p-4 shadow-sm\">\r\n        <div className=\"mb-3 flex flex-wrap items-center justify-between gap-2\">\r\n          <div>\r\n            <p className=\"text-xs font-black uppercase tracking-widest text-blue-600\">Bảng lương tháng</p>\r\n          </div>\r\n          <div className=\"flex items-center gap-2\">\r\n            <button type=\"button\" onClick={handleCreatePayrollPdf} className=\"inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-1.5 text-xs font-black text-emerald-700\" aria-label=\"Tạo PDF bảng lương\">\r\n              <Download size={13} /> PDF\r\n            </button>\r\n            <button type=\"button\" onClick={() => setActiveTab('payroll')} className=\"rounded-full bg-blue-50 px-3 py-1.5 text-xs font-black text-blue-700\">Chi tiết</button>\r\n          </div>\r\n        </div>\r\n        <div className=\"space-y-2\">\r\n          {payrollSummaryRows.map(row => (\r\n            <EmployeeHomeQuickRow\r\n              key={row.label}\r\n              label={row.label}\r\n              value={`${formatCurrency(row.amount)} đ`}\r\n              tone={row.tone || (row.amount === 0 ? 'slate' : row.group === 'deduction' ? 'bad' : 'good')}\r\n            />\r\n          ))}\r\n        </div>\r\n        {payrollPdfStatus && <p className=\"mt-3 rounded-2xl bg-slate-50 px-3 py-2 text-xs font-bold text-slate-600\" role=\"status\">{payrollPdfStatus}</p>}\r\n      </section>\r\n\r\n      <div ref={payrollPdfRef} aria-hidden=\"true\" className=\"pointer-events-none absolute -left-[10000px] top-0 w-[794px] bg-white p-10 text-slate-900\">\r\n        <div className=\"border-b-2 border-slate-900 pb-4 text-center\">\r\n          <p className=\"text-lg font-black uppercase\">{currentCompany?.name || currentCompany?.companyName || 'CÔNG TY'}</p>\r\n          <p className=\"mt-1 text-2xl font-black uppercase\">BẢNG THANH TOÁN TIỀN LƯƠNG</p>\r\n          <p className=\"mt-1 text-base font-bold\">Tháng {formatMonthYearLabel(monthKey)}</p>\r\n        </div>\r\n        <div className=\"mt-6 grid grid-cols-2 gap-x-8 gap-y-2 text-base\">\r\n          <p><strong>Họ và tên:</strong> {employee?.name || '-'}</p>\r\n          <p><strong>Bộ phận:</strong> {positionLabel || '-'}</p>\r\n          <p><strong>Kỳ lương:</strong> {monthKey}</p>\r\n          <p><strong>Ngày công:</strong> {formatNumber(details.workDays)}</p>\r\n        </div>\r\n        <table className=\"mt-6 w-full border-collapse text-base\">\r\n          <thead>\r\n            <tr className=\"bg-slate-100\">\r\n              <th className=\"border border-slate-700 px-3 py-2 text-center\">STT</th>\r\n              <th className=\"border border-slate-700 px-3 py-2 text-left\">Nội dung</th>\r\n              <th className=\"border border-slate-700 px-3 py-2 text-right\">Số tiền (VNĐ)</th>\r\n            </tr>\r\n          </thead>\r\n          <tbody>\r\n            {payrollSummaryRows.map((row, index) => (\r\n              <tr key={`pdf-${row.label}`}>\r\n                <td className=\"border border-slate-700 px-3 py-2 text-center\">{index + 1}</td>\r\n                <td className=\"border border-slate-700 px-3 py-2\">{row.label}</td>\r\n                <td className=\"border border-slate-700 px-3 py-2 text-right\">{formatCurrency(row.amount)}</td>\r\n              </tr>\r\n            ))}\r\n          </tbody>\r\n        </table>\r\n        <div className=\"mt-8 grid grid-cols-2 gap-8 text-center text-base\">\r\n          <div><p className=\"font-bold\">Người lập bảng</p><p className=\"mt-16\">{employee?.name || ''}</p></div>\r\n          <div><p className=\"font-bold\">Người nhận lương</p><p className=\"mt-16\">{employee?.name || ''}</p></div>\r\n        </div>\r\n      </div>\r\n\r\n      {showDeliveryReportHome && (\r\n      <section className=\"rounded-[2rem] border border-slate-100 bg-white p-4 shadow-sm\">\r\n        <div className=\"mb-3 flex items-center justify-between gap-2\">\r\n          <div>\r\n            <p className=\"text-xs font-black uppercase tracking-widest text-emerald-600\">Báo cáo giao hàng</p>\r\n          </div>\r\n          <span className=\"rounded-full bg-emerald-50 px-3 py-1 text-xs font-black text-emerald-700\">\r\n            {formatNumber(employeeDeliveryMonthSummary.reportCount)} báo cáo\r\n          </span>\r\n        </div>\r\n        <div className=\"grid grid-cols-2 gap-2\">\r\n          <EmployeeHomeStatCard label=\"Thu\" value={`${formatCurrency(employeeDeliveryMonthSummary.income)} đ`} tone={employeeDeliveryMonthSummary.income > 0 ? 'emerald' : 'slate'} />\r\n          <EmployeeHomeStatCard label=\"Chi\" value={`${formatCurrency(employeeDeliveryMonthSummary.expense)} đ`} tone={employeeDeliveryMonthSummary.expense > 0 ? 'amber' : 'slate'} />\r\n        </div>\r\n        {employeeDeliveryMonthSummary.rows.length > 0 ? (\r\n          <div className=\"mt-3 overflow-hidden rounded-3xl border border-slate-100\">\r\n            <div className=\"grid grid-cols-[1fr_1fr_1fr] bg-slate-50 px-3 py-2 text-[10px] font-black uppercase tracking-wide text-slate-500\">\r\n              <span>Ngày</span>\r\n              <span className=\"text-center\">Thu</span>\r\n              <span className=\"text-right\">Chi</span>\r\n            </div>\r\n            {employeeDeliveryMonthSummary.rows.slice(0, 8).map(row => (\r\n              <div key={row.date} className=\"grid grid-cols-[1fr_1fr_1fr] items-center border-t border-slate-100 px-3 py-2 text-xs font-bold text-slate-700\">\r\n                <span>{formatDateLabel(row.date)}{row.reportCount ? ` • ${formatNumber(row.reportCount)}` : ''}</span>\r\n                <span className=\"text-center text-emerald-700\">{formatCurrency(row.income)} đ</span>\r\n                <span className=\"text-right text-amber-700\">{formatCurrency(row.expense)} đ</span>\r\n              </div>\r\n            ))}\r\n          </div>\r\n        ) : (\r\n          <p className=\"mt-3 rounded-2xl bg-slate-50 px-3 py-2 text-xs font-semibold text-slate-500\">\r\n            Chưa có báo cáo giao hàng nào trong tháng này.\r\n          </p>\r\n        )}\r\n        <button type=\"button\" onClick={() => setActiveTab('delivery_reports')} className=\"mt-3 w-full rounded-2xl bg-emerald-600 px-4 py-3 text-sm font-black text-white shadow-lg shadow-emerald-100\">\r\n          Mở báo cáo giao hàng\r\n        </button>\r\n      </section>\r\n      )}\r\n\r\n    </div>\r\n  );\r\n}";
